class Solution {
public:
    int minDeletion(vector<int>& nums) {
        int n = nums.size();
        int kept = 0;
        int deletions = 0;
        int last = -1;
        for (int i = 0; i < n; i++) {
            if (kept % 2 == 0) {
                last = nums[i];
                kept++;
            } else {
                if (nums[i] != last) {
                    last = nums[i];
                    kept++;
                } else {
                    deletions++;
                }
            }
        }
        if (kept % 2 == 1) deletions++;
        return deletions;
    }
};
